#!/usr/bin/env bash
# wake-pi.sh — hand a fresh handoff to pi.
# Generated by `install.sh --target pi`.
#
# Pi is driven from the agent-skill side; this is the *external scheduler* path:
# the supervisor starts pi headlessly with the handoff as its prompt. pi has no
# `run` subcommand — `--print` is its non-interactive mode (`pi --print
# "<prompt>"`). Pass a session id as the second argument to resume that session
# (`pi --print --session <sid> "<prompt>"`). If your pi build differs, wire the
# supervisor's `--wake-command` to your own glue, or use the in-session trigger
# described in docs/scheduling.md (the supervisor still does the scan, the
# atomic claim, and the patrol; only the wake is manual).
#
#   wake-pi.sh "<handoff>"            # a fresh headless turn
#   wake-pi.sh "<handoff>" <sid>      # resume session <sid>
set -eu

prompt="${1:-}"
sid="${2:-}"

if [ -z "$prompt" ]; then
  echo "wake-pi: a handoff prompt is required" >&2
  exit 2
fi

if [ -n "$sid" ]; then
  exec pi --print --session "$sid" "$prompt"
fi

exec pi --print "$prompt"
